package com.intellilib.server.web;
import com.intellilib.server.model.ApiModels.*; import com.intellilib.server.security.*; import com.intellilib.server.service.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/me") public class StudentController { private final AuthService auth; private final CirculationService circ; private final NotificationService notifications; public StudentController(AuthService a,CirculationService c,NotificationService n){auth=a;circ=c;notifications=n;} @PostMapping("/requests/{bookId}") public Map<String,Object> request(@PathVariable long bookId,HttpServletRequest req){SessionUser u=auth.requireStudent(AuthHeader.token(req));long id=circ.request(u.id(),bookId);return Map.of("ok",true,"requestId",id);} @GetMapping("/requests") public List<BorrowRequestView> requests(HttpServletRequest req){SessionUser u=auth.requireStudent(AuthHeader.token(req));return circ.myRequests(u.id());} @GetMapping("/loans") public List<LoanView> loans(HttpServletRequest req){SessionUser u=auth.requireStudent(AuthHeader.token(req));return circ.myLoans(u.id());} @GetMapping("/notifications") public List<NotificationView> notes(HttpServletRequest req){SessionUser u=auth.requireStudent(AuthHeader.token(req));return notifications.list(u.id());} }
